function zhxEnsureDict() {
  zhxDictPromise ??= (async () => {
    const rows = await (await self.LENS.fetchData("jawi", "dict.json.gz")).json();
    zhxIndex = new Map();
    const add = (key, entry) => {
      if (!key) return;
      const list = zhxIndex.get(key);
      if (list) { if (list.length < 8) list.push(entry); } else zhxIndex.set(key, [entry]);
    };
    for (const [w, extra, gloss] of rows) {
      const entry = { w, x: extra, g: gloss };
      add(zhxBare(extra), entry); if (w) add(w.toLowerCase(), entry);
    }
  })();
  return zhxDictPromise;
}

// A gloss that is only a grammatical pointer ("(verb) inflection of estar") with no
// real definition. These should rank below entries that actually define the word.
const ZHX_POINTER_RE = /^(\([^)]*\)\s*)?(strong|weak|mixed|inflection|plural|singular|feminine|masculine|neuter|comparative|superlative|diminutive|augmentative|past participle|present participle|verbal noun|active participle|passive participle|gerund|infinitive|conjugation|imperative|subjunctive|indicative|preterite|(?:first|second|third)(?:\/(?:first|second|third))*-person|nominative|genitive|dative|accusative|vocative|construct|dual|alternative|excessive spelling|defective spelling|active|passive|causative|reflexive)\b[^;]*\bof\b/i;
function zhxRankList(list) {
  return [...list].sort((a, b) => (ZHX_POINTER_RE.test(a.g) ? 1 : 0) - (ZHX_POINTER_RE.test(b.g) ? 1 : 0));
}

function zhxLookupWord(word) {
  const bare = zhxBare(word);
  for (const cand of zhxCandidates(word)) {
    const list = zhxIndex.get(cand);
    if (list) {
      // A match reached only by removing a single leading clitic letter (Arabic و/ف/ب/ك/ل,
      // Hebrew single-letter proclitics) is unreliable — it can land on an unrelated word
      // (كتبت→تبت "Tibet"). Flag it so the UI shows the result as uncertain rather than
      // confidently wrong. Multi-letter prefix strips (ال, וה) stay trusted.
      const risky = cand !== bare && bare.endsWith(cand) && bare.length - cand.length === 1;
      return { matched: cand, list, risky };
    }
  }
  return null;
}

// Reduplication note (Malay 词-doubling carries meaning): kanak-kanak = plural,
// sayur-sayuran = variety, tolong-menolong = reciprocal.
function zhxRedup(word) {
  const hy = word.indexOf('-');
  if (hy <= 0) return undefined;
  const a = word.slice(0, hy).toLowerCase();
  const b = word.slice(hy + 1).toLowerCase();
  if (a === b) return 'reduplication — plural or repetition of "' + a + '"';
  if (b === a + 'an' || b === a + 'kan') return 'reduplication — variety/collective of "' + a + '"';
  if (/^(me|men|mem|meng|meny)/.test(b) && b.length > 3) return 'reduplication — reciprocal (doing "' + a + '" to one another)';
  return undefined;
}

// Interlinear gloss: a short per-word meaning attached to selection tokens, so a whole
// sentence can be understood by reading ACROSS the line instead of clicking each word.
// Uses the full candidate machinery (case, elision, affix stripping), prefers a real
